edits.oldText:
export function composeChildPrompt(input: {
	family: PromptFamily;
	rolePrompt: string;
	includesFamilyShared?: boolean;
	root?: string;
}): { family: PromptFamily; text: string; files: string[] } {
	const rolePrompt = input.rolePrompt.trim();
	if (input.includesFamilyShared || input.family === "pi-default") {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	const shared = familySharedBody(input.family, input.root).trim();
	if (!shared) {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	if (rolePrompt.includes(shared)) {
		return {
			family: input.family,
			text: rolePrompt,
			files: [`${input.family}/shared.md`, "role"],
		};
	}
	const text = [shared, rolePrompt].filter(Boolean).join("\n");
	return {
		family: input.family,
		text,
		files: rolePrompt ? [`${input.family}/shared.md`, "role"] : [`${input.family}/shared.md`],
	};
}

edits.newText:
export function composeChildPrompt(input: {
	family: PromptFamily;
	rolePrompt: string;
	includesFamilyShared?: boolean;
	common?: boolean;
	root?: string;
}): { family: PromptFamily; text: string; files: string[] } {
	const rolePrompt = input.rolePrompt.trim();
	let text: string;
	let files: string[];
	if (input.includesFamilyShared || input.family === "pi-default") {
		text = rolePrompt;
		files = rolePrompt ? ["role"] : [];
	} else {
		const shared = familySharedBody(input.family, input.root).trim();
		if (!shared) {
			text = rolePrompt;
			files = rolePrompt ? ["role"] : [];
		} else if (rolePrompt.includes(shared)) {
			text = rolePrompt;
			files = [`${input.family}/shared.md`, "role"];
		} else {
			text = [shared, rolePrompt].filter(Boolean).join("\n");
			files = rolePrompt ? [`${input.family}/shared.md`, "role"] : [`${input.family}/shared.md`];
		}
	}
	if (input.common && input.family !== "pi-default") {
		const common = commonBody(input.root).trim();
		if (common && !text.includes(common)) {
			text = [text, common].filter(Boolean).join("\n");
			files = [...files, "common.md"];
		} else if (common && text.includes(common)) {
			if (!files.includes("common.md")) files = [...files, "common.md"];
		}
	}
	return { family: input.family, text, files };
}

